      wrong: ["影響他人的決定都應保留可複查證據。", "可靠比快速更值得優先考量。", "判斷標準不應隨個人偏好任意改變。"],
      reason: "正解是文本記錄的個案行動與結果；其餘三項都是作者提出的規範或評價。",
